import{_ as e,o as a,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"技术决策总览","description":"","frontmatter":{"title":"技术决策总览"},"headers":[],"relativePath":"frontend/decisions/index.md","filePath":"frontend/decisions/index.md","lastUpdated":1785589115000}'),d={name:"frontend/decisions/index.md"};function n(o,t,l,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="技术决策总览" tabindex="-1">技术决策总览 <a class="header-anchor" href="#技术决策总览" aria-label="Permalink to &quot;技术决策总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>技术决策不是寻找脱离场景的“最佳方案”，而是在明确约束下选择代价可接受的方案。高质量决策需要事实、比较标准、风险意识和可追溯记录，也需要知道何时应该推迟、试验或撤销决定。</p><p>本模块不重复介绍工具和框架的全部知识，而是聚焦它们进入真实项目时的选择条件、组合方式和长期成本。</p><h2 id="决策地图" tabindex="-1">决策地图 <a class="header-anchor" href="#决策地图" aria-label="Permalink to &quot;决策地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>典型问题</th><th>主要评价维度</th></tr></thead><tbody><tr><td><a href="/frontend/decisions/decision-framework">决策方法</a></td><td>如何形成、记录、采购和复查决定</td><td>目标、证据、风险、可逆性、总拥有成本</td></tr><tr><td><a href="/frontend/decisions/architecture/modularization">架构与代码边界</a></td><td>如何划分系统，何时引入分布式或扩展机制</td><td>变更耦合、团队边界、独立交付、演进成本</td></tr><tr><td><a href="/frontend/decisions/rendering/rendering-strategy">渲染与运行时</a></td><td>页面在哪里生成，代码在哪里运行和托管</td><td>可索引性、个性化、缓存、延迟、运行成本</td></tr><tr><td><a href="/frontend/decisions/tooling/framework-selection">工具链</a></td><td>UI 框架、元框架、构建与包管理如何选择</td><td>团队能力、生态、性能、迁移、维护周期</td></tr><tr><td><a href="/frontend/decisions/data/state-management">状态与数据</a></td><td>状态、API、实时通信和缓存如何分工</td><td>所有权、一致性、延迟、离线、服务端能力</td></tr><tr><td><a href="/frontend/decisions/ui/css-strategy">UI 工程</a></td><td>样式、组件抽象、组件库和设计系统如何治理</td><td>一致性、复用范围、定制成本、治理能力</td></tr><tr><td><a href="/frontend/decisions/quality/testing-strategy">质量与交付</a></td><td>测试、监控、迁移、发布和回滚如何投入</td><td>业务风险、反馈速度、恢复能力、退出成本</td></tr></tbody></table><h2 id="硬约束先于评分" tabindex="-1">硬约束先于评分 <a class="header-anchor" href="#硬约束先于评分" aria-label="Permalink to &quot;硬约束先于评分&quot;">​</a></h2><p>评价矩阵只适用于已经满足硬约束的候选方案。安全、隐私、许可证、监管、数据驻留、最低浏览器版本和既有合同等要求，应先作为淘汰条件检查，不能用“开发更快”或“成本更低”的高分抵消。</p><p>例如某监控 SaaS 无法满足数据驻留要求，即使接入成本最低，也不应进入加权评分；正确动作是淘汰该候选，或先确认脱敏、私有化部署等措施能否消除冲突。</p><h2 id="决策流程" tabindex="-1">决策流程 <a class="header-anchor" href="#决策流程" aria-label="Permalink to &quot;决策流程&quot;">​</a></h2><ol><li><strong>定义问题</strong>：写清业务目标、受影响对象和维持现状的后果。</li><li><strong>识别硬约束</strong>：先淘汰不合规、不兼容或越过安全边界的方案。</li><li><strong>确定标准</strong>：在比较前约定评价维度、权重和证据门槛。</li><li><strong>形成选项</strong>：把维持现状列为候选，避免把预设答案包装成比较。</li><li><strong>收集证据</strong>：用文档、原型、基准测试和历史数据降低关键不确定性。</li><li><strong>评估全周期代价</strong>：同时考虑引入、运行、迁移、退出和认知成本。</li><li><strong>记录决定</strong>：使用 <a href="/frontend/decisions/adr">ADR</a> 保存结论、后果和复查条件。</li><li><strong>验证与复查</strong>：观察真实结果，在指标越界或前提变化时重新评估。</li></ol><h2 id="决策分级" tabindex="-1">决策分级 <a class="header-anchor" href="#决策分级" aria-label="Permalink to &quot;决策分级&quot;">​</a></h2><p>并非所有选择都值得召开评审或编写长文档：</p><ul><li>局部且容易撤销的决定，应快速试验并保留基本记录。</li><li>跨模块、跨团队或迁移成本高的决定，需要明确评审和 ADR。</li><li>信息不足但影响重大的决定，应先通过原型或限量发布获取证据。</li><li>已有组织标准覆盖的决定，优先复用标准，同时允许基于证据提出例外。</li></ul><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li><a href="/frontend/guide/core/">核心知识</a>说明候选技术的能力和限制。</li><li><a href="/frontend/guide/engineering/">工程体系</a>提供测试、性能、发布和监控等评价手段。</li><li>本模块组织比较过程并记录选择，不替代具体实现。</li><li><a href="/frontend/practices/">项目实战</a>检验决定在真实约束下产生的结果。</li><li>浏览器基线、身份认证与安全方案是工程约束，不在这里改写为偏好比较。</li></ul><h2 id="高质量决策的标准" tabindex="-1">高质量决策的标准 <a class="header-anchor" href="#高质量决策的标准" aria-label="Permalink to &quot;高质量决策的标准&quot;">​</a></h2><ul><li>问题和约束比方案描述更清楚。</li><li>比较维度在结论之前确定，并且可以被他人审查。</li><li>既记录收益，也记录被接受的缺点和退出成本。</li><li>明确决定的负责人、有效范围、复查时间或触发条件。</li><li>新证据出现时能够修正决定，而不是维护个人立场。</li></ul>',18)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
